import importlib.metadata,importlib.util,json,platform,subprocess,sys,tomllib
from pathlib import Path
root=Path.cwd()
packages={item.metadata['Name']:item.version for item in importlib.metadata.distributions()}
lock={item['name'].lower().replace('_','-'):item['version'] for item in tomllib.loads((root/'uv.lock').read_text())['package']}
for name,version in packages.items():assert lock[name.lower().replace('_','-')]==version,(name,version)
assert all(importlib.util.find_spec(name) is None for name in ['mlx','mlx_lm','torch','transformers'])
blocks={}
for name in ['.venv','.toolalign-local/review-p03']:
 result=subprocess.check_output(['du','-sk',name],text=True).split()[0]
 blocks[name]=int(result)*1024
record={'python':sys.version.split()[0],'platform':platform.platform(),'machine':platform.machine(),'distributions':packages,'allocated_disk_bytes':blocks,'all_installed_versions_match_lock':True,'model_packages_available':[]}
Path('.toolalign-local/review-p03/environment.json').write_text(json.dumps(record,indent=2,sort_keys=True)+'\n')
print(json.dumps(record,indent=2,sort_keys=True))
